Definition agsh (a n : Z) : Prop := forall x, a <= x < a + n -> M' (Z_to_bv 64 (S x)) = M (Z_to_bv 64 (S x)).
Definition agA (a n : Z) : Prop := ag a n /\ agsh a n.

