Lemma iss_st_updA (M M' : word -> option byte) ois str g eg st st' :
  PM.iss_at RSEGS PMA.AD PMSPA.accA M ois str (PM.STRM g eg st) -> 0 <= ois -> ois + 272 <= 2 ^ 64 ->
