  (forall c n p, str = PM.VLong c n p -> PMFA.agA M M' p c) ->
  L5.u32_at RSEGS M' (ois + 152) st' -> st' = 0 \/ st' = 2 ->
  PM.iss_at RSEGS PMA.AD PMSPA.accA M' ois str (PM.STRM g eg st').
