    Z.of_nat (length stk) <= old <= 2 ^ k ->
    (* [comment removed for export] *)
    L5.u64_at segs M v b -> L5.u64_at segs M (v + 8) (b + BSZ * Z.of_nat (length stk)) -> L5.u64_at segs M (v + 16) (b + BSZ * 2 ^ k) ->
