(* [comment removed for export] *)
(* [comment removed for export] *)
Definition mstack_shape (stk : list PQMA.mstate) : Prop :=
  (1 <= length stk)%nat /\ Z.of_nat (length stk) <= PQMA.MAX_DEPTH + 1
  /\ PQMA.mode_bottom (PQMA.ms_mode (nth 0 stk PQMA.ms_root))
  /\ (forall i, (1 <= i < length stk)%nat -> PQMA.mode_cont (PQMA.ms_mode (nth i stk PQMA.ms_root)))
  /\ (forall i, (i < length stk)%nat -> PQMA.mstate_ok (nth i stk PQMA.ms_root)).
(* [comment removed for export] *)
Definition minv_d (d : Z) (s : PQMA.mpst) : Prop :=
  PQMA.p_more s = 1 /\ PQMA.p_done s = 0 /\ PQMA.p_depth s = Z.of_nat (length (PQMA.p_stk s)) - 1 + d /\ mstack_shape (PQMA.p_stk s).
Definition minv (s : PQMA.mpst) : Prop := minv_d 0 s.
Definition mmu (s : PQMA.mpst) (sm : PM.strm) : Z := 4096 * PM.unread (PQMA.p_src s) sm + 2 * Z.of_nat (length (PQMA.p_stk s)).

(* [comment removed for export] *)
Definition mpush1 (s s' : PQMA.mpst) : Prop :=
  exists c, PQMA.p_stk s' = PQMA.p_stk s ++ [c] /\ PQMA.mstate_ok c /\ PQMA.ms_idx c = 0 /\ (PQMA.ms_mode c = 2 \/ PQMA.ms_mode c = 3).
Definition mpush_rel (s s' : PQMA.mpst) : Prop := PQMA.p_stk s' = PQMA.p_stk s \/ mpush1 s s'.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition pot_callM (L : heap_layout) (n : Z) : credit :=
  PM.credit_add (PM.credit_add (PM.cost1 L (n + 16)) (PM.cost1 L (n + 32)))
    (PM.credit_add (PM.credit_add (PM.cost1 L PM.CHUNK) (PM.credit_add (PM.cost1 L PQMA.PSZ) (PM.cost1 L PQMA.LSZ)))
       (PM.credit_add
          (PQMA.pot_run L
             (PQMA.MPST 1 0 0 (PM.SRC 0 0 0) (PM.VShort 0) 0 PGV8.V8Null 0 0 0 [])
             (PQMA.AST [] 0 0 (PM.VShort 0) 0 (PM.VShort 0) 0))
          PQMA.TSRES)).

Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable AQ : pq_addrs.
Variable AA : pm_asan_addrs.
