(* [comment removed for export] *)
Abbreviation accA := PMSPA.accA.
Definition annA : (word -> option byte) -> Z -> Z -> Z -> Prop := fun M b u c => HAJ.ann_shadow M b u c.
Abbreviation iss_at := (PM.iss_at segs A accA).
Abbreviation mparser_at := (PQMA.mparser_at segs A accA annA (pa_vp_parser A)).
Abbreviation adaptor_at := (PQMA.adaptor_at segs A accA annA (qa_vp_adaptor AQ)).
Abbreviation err_ok := (PQSTA.err_okA segs A AA AQ).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSP.cfg segs).
Abbreviation HV := (PMSPA.HV L ar).
(* [comment removed for export] *)
Definition FCM : list Z := PNRA.FCB.
Abbreviation ffroomM := (PGSA.ffroomB FCM).
(* [comment removed for export] *)
Definition frame_okM (FF : list fframe) (fb : Z) : Prop := (exists rs, In (fb, 5, rs) FF) /\ fb mod 2048 = 0.

(* [comment removed for export] *)
Definition o_p (fb : Z) : Z := PMSP.o_p A fb.
Definition o_a (fb : Z) : Z := o_p fb + qa_off_a AQ.
Definition o_v (fb : Z) : Z := PMSP.o_v A fb.
Definition o_is (fb : Z) : Z := PMSP.o_is A fb.
Definition o_ec (fb : Z) : Z := PMSP.o_ec A fb.
Definition o_src (fb : Z) : Z := o_p fb + PQMA.OFF_SRC.
Definition o_tb (fb : Z) : Z := o_p fb + PQMA.OFF_TB.
Definition o_bb (fb : Z) : Z := o_p fb + PQMA.OFF_BB.
Definition o_stk (fb : Z) : Z := o_p fb + PQMA.OFF_STK.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition make_ec_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o v sp r : Z) (b : bool),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r 1 -> ffroomM 1 FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 v -> 1 <= v <= 64 ->
    aobjA FF o 16 -> o mod 8 = 0 -> L5.defined M o 16 -> accA M o 16 ->
    PMSTA.base_okA segs A M -> err_ok M b ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)),
        regs_preserved R R' -> PMSPA.ec_at segs M' o v (pa_errcat_obj A) -> err_ok M' true ->
        L5CA.ahpres L ar LB FF sp (pm_scr 1) ((o, 16) :: (if b then [] else PMSP.err_W A)) M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI LB FF LK' cr Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (pa_make_ec A) M model) K.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition mrun_pre (M : word -> option byte) (fb : Z) (s : PQMA.mpst) (st : PQMA.ast) (str : PM.vstr) (sm : PM.strm) (e : bool)
           (n : Z) : Prop :=
  mparser_at M (o_p fb) (o_is fb) s /\ adaptor_at M (o_a fb) (o_v fb) st /\ iss_at M (o_is fb) str sm
  /\ PMSPA.visitor_at segs A M (o_v fb) /\ L5.u64_at segs M (o_p fb + qa_off_vref AQ) (o_a fb)
  /\ accA M (o_p fb) 504
  /\ PMSTA.base_okA segs A M /\ err_ok M e /\ PQMA.mgrow_ok s /\ PQMA.adaptor_ok st /\ PQMA.cpl s st /\ PQMA.acct n s st sm.
Definition W_mrun (fb : Z) : list L5.range :=
  [(o_p fb + 8, 8)] ++ PGS.W_srcfG (o_src fb) (o_is fb) ++ [(o_tb fb, 24); (o_bb fb, 24); (o_stk fb, 24); (o_ec fb, 16)]
  ++ PMSP.err_W A ++ PQMA.adaptor_W A (o_a fb).
Definition mown (s : PQMA.mpst) (st : PQMA.ast) : list (Z * Z) := PQMA.mparser_own s ++ PQMA.aown st.

Definition mprog := bvmap 5 word -> (word -> option byte) -> PQMA.mpst -> PQMA.mpst -> PQMA.ast -> PQMA.ast -> PM.strm -> PM.strm -> Prop.
(* [comment removed for export] *)
Definition bb_room (s : PQMA.mpst) (sm : PM.strm) : Prop := PGV8.v8_room (PQMA.p_bb s) (PM.unread (PQMA.p_src s) sm).
Definition room_keep (s s' : PQMA.mpst) (sm sm' : PM.strm) : Prop := bb_room s sm -> bb_room s' sm'.
Lemma room_keep_same s s' sm sm' :
  PQMA.p_bb s' = PQMA.p_bb s -> PM.unread (PQMA.p_src s') sm' <= PM.unread (PQMA.p_src s) sm -> room_keep s s' sm sm'.
Proof. unfold room_keep, bb_room. intros E U H. rewrite E. exact (PGV8.v8_room_mono _ _ _ U H). Qed.
Lemma room_keep_step s s' sm sm' :
  PQMA.p_bb s' = PQMA.p_bb s -> PMSP.src_step (PQMA.p_src s) (PQMA.p_src s') sm sm' -> room_keep s s' sm sm'.
Proof. intros E (_ & _ & _ & _ & U). exact (room_keep_same s s' sm sm' E U). Qed.
Lemma room_keep_trans s s1 s2 sm sm1 sm2 : room_keep s s1 sm sm1 -> room_keep s1 s2 sm1 sm2 -> room_keep s s2 sm sm2.
Proof. unfold room_keep. auto. Qed.
Lemma room_keep_refl s sm : room_keep s s sm sm.
Proof. unfold room_keep. auto. Qed.
Definition mrun_post_d (d : Z) (prog : mprog) (R' : bvmap 5 word) (M' : word -> option byte) (fb : Z) (s s' : PQMA.mpst)
           (st st' : PQMA.ast) (str : PM.vstr) (sm sm' : PM.strm) (e e' : bool) (cat n : Z) : Prop :=
  mrun_pre M' fb s' st' str sm' e' n /\ PMSP.src_step (PQMA.p_src s) (PQMA.p_src s') sm sm' /\ (e = true -> e' = true)
  /\ (   (exists v, 1 <= v <= 64 /\ PMSPA.ec_at segs M' (o_ec fb) v (pa_errcat_obj A) /\ PQMA.p_more s' = 0 /\ e' = true)
      \/ (PMSPA.ec_at segs M' (o_ec fb) 0 cat /\ minv_d d s' /\ prog R' M' s s' st st' sm sm' /\ room_keep s s' sm sm')).

(* [comment removed for export] *)
Definition mrun_spec_d (pc h d : Z) (args : bvmap 5 word -> Z -> PQMA.mpst -> PQMA.ast -> PM.strm -> Z -> Prop) (prog : mprog) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb cat n : Z) (s : PQMA.mpst) (st : PQMA.ast) (str : PM.vstr) (sm : PM.strm) (e : bool),
    ri_inv HI (mown s st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r h -> ffroomM h FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    args R fb s st sm n ->
    mrun_pre M fb s st str sm e n -> incl (PM.vs_own str) LBX -> minv_d d s -> PMSPA.ec_at segs M (o_ec fb) 0 cat ->
    PMSP.credit_le (PMSPA.scA L (PM.credit_add (PQMA.pot_run HV s st) PQMA.TSRES)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : PQMA.ast)
            (sm' : PM.strm) (e' : bool) (cr' : credit),
        regs_preserved R R' ->
        mrun_post_d d prog R' M' fb s s' st st' str sm sm' e e' cat n ->
        L5CA.ahpres L ar LBX FF sp (pm_scr h) (W_mrun fb) M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_run HV s st)) (PMSPA.scA L (PQMA.pot_run HV s' st')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
Definition mrun_spec (pc h : Z) (args : bvmap 5 word -> Z -> PQMA.mpst -> PQMA.ast -> PM.strm -> Z -> Prop) (prog : mprog) : Prop :=
  mrun_spec_d pc h 0 args prog.

(* [comment removed for export] *)
Definition margs3 (R : bvmap 5 word) (fb : Z) (_ : PQMA.mpst) (_ : PQMA.ast) (_ : PM.strm) (_ : Z) : Prop :=   (* [comment removed for export] *)
  getr R 10%bv = Z_to_bv 64 (o_p fb) /\ getr R 11%bv = Z_to_bv 64 (o_a fb) /\ getr R 12%bv = Z_to_bv 64 (o_ec fb).
(* [comment removed for export] *)
Definition ba_type (t : Z) : Prop := (144 <= t <= 159) \/ t = 220 \/ t = 221.
Definition bo_type (t : Z) : Prop := (128 <= t <= 143) \/ t = 222 \/ t = 223.
Definition margs_begin (P : Z -> Prop) (R : bvmap 5 word) (fb : Z) (s : PQMA.mpst) (st : PQMA.ast) (sm : PM.strm) (n : Z) : Prop :=
  getr R 10%bv = Z_to_bv 64 (o_p fb) /\ getr R 11%bv = Z_to_bv 64 (o_a fb) /\ getr R 13%bv = Z_to_bv 64 (o_ec fb)
  /\ (exists t, P t /\ getr R 12%bv = Z_to_bv 64 t) /\ PQMA.acct_d 4 n s st sm.
(* [comment removed for export] *)
Definition gs_type (t : Z) : Prop := (128 <= t <= 159) \/ (196 <= t <= 201) \/ (212 <= t <= 223).
Definition margs_gs (R : bvmap 5 word) (fb : Z) (_ : PQMA.mpst) (_ : PQMA.ast) (_ : PM.strm) (_ : Z) : Prop :=
  getr R 10%bv = Z_to_bv 64 (o_p fb) /\ getr R 12%bv = Z_to_bv 64 (o_ec fb) /\ exists t, gs_type t /\ getr R 11%bv = Z_to_bv 64 t.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition mprog_item : mprog := fun R' M' s s' st st' sm sm' =>
  mpush_rel s s' /\ PM.unread (PQMA.p_src s') sm' < PM.unread (PQMA.p_src s) sm.
(* [comment removed for export] *)
Definition mprog_push : mprog := fun R' M' s s' st st' sm sm' =>
  mpush1 s s' /\ PM.unread (PQMA.p_src s') sm' <= PM.unread (PQMA.p_src s) sm.
(* [comment removed for export] *)
Definition mprog_len : mprog := fun R' M' s s' st st' sm sm' =>
  PQMA.p_stk s' = PQMA.p_stk s /\ st' = st /\ PM.unread (PQMA.p_src s') sm' <= PM.unread (PQMA.p_src s) sm
  /\ exists len, 0 <= len < 2 ^ 64 /\ getr R' 10%bv = Z_to_bv 64 len.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition get_size_spec : Prop := forall d, 0 <= d <= 1 -> mrun_spec_d (qa_get_size AQ) 5 d margs_gs mprog_len.
Definition begin_array_spec : Prop := mrun_spec (qa_begin_array AQ) 6 (margs_begin ba_type) mprog_push.
Definition begin_object_spec : Prop := mrun_spec (qa_begin_object AQ) 6 (margs_begin bo_type) mprog_push.
(* [comment removed for export] *)
Definition margs_ri (R : bvmap 5 word) (fb : Z) (s : PQMA.mpst) (st : PQMA.ast) (sm : PM.strm) (n : Z) : Prop :=
  margs3 R fb s st sm n /\ bb_room s sm.
Definition read_item_spec : Prop := mrun_spec (qa_read_item AQ) 7 margs_ri mprog_item.

(* [comment removed for export] *)
Definition mpst_reset (s : PQMA.mpst) : PQMA.mpst :=
  PQMA.MPST 1 0 0 (PQMA.p_src s)
           (match PQMA.p_tb s with PM.VShort _ => PM.VShort 0 | PM.VLong c _ p => PM.VLong c 0 p end) (PQMA.p_tg s)
           (PGV8.v8_clear (PQMA.p_bb s)) (PQMA.p_bg s) (PQMA.p_sb s) (PQMA.p_sk s) [PQMA.ms_root].
Definition reset_W (fb : Z) : list L5.range := [(o_p fb + 8, 8); (o_tb fb, 24); (o_bb fb, 24); (o_stk fb, 24)].
Definition reset_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb : Z) (s : PQMA.mpst),
    ri_inv HI (PQMA.mparser_own s ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r 1 -> ffroomM 1 FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    getr R 10%bv = Z_to_bv 64 (o_p fb) -> mparser_at M (o_p fb) (o_is fb) s -> accA M (o_p fb) PQMA.PSIZE -> PMSTA.base_okA segs A M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)),
        regs_preserved R R' -> mparser_at M' (o_p fb) (o_is fb) (mpst_reset s) ->
        (* [comment removed for export] *)
        L5CA.ahpres L ar LBX FF sp (pm_scr 1) (reset_W fb) M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (PQMA.mparser_own s ++ LBX) FF LK' cr Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (qa_reset AQ) M model) K.

(* [comment removed for export] *)
Definition mrun_fin (M : word -> option byte) (fb : Z) (s : PQMA.mpst) (st : PQMA.ast) (str : PM.vstr) (sm : PM.strm) (e : bool) : Prop :=
  mparser_at M (o_p fb) (o_is fb) s /\ adaptor_at M (o_a fb) (o_v fb) st /\ iss_at M (o_is fb) str sm
  /\ PMSPA.visitor_at segs A M (o_v fb) /\ L5.u64_at segs M (o_p fb + qa_off_vref AQ) (o_a fb)
  /\ accA M (o_p fb) 504
  /\ PMSTA.base_okA segs A M /\ err_ok M e /\ PQMA.mgrow_ok s /\ PQMA.adaptor_ok st.
Definition parse_post (M' : word -> option byte) (fb : Z) (s s' : PQMA.mpst) (st' : PQMA.ast) (str : PM.vstr) (sm sm' : PM.strm)
           (e e' : bool) (n : Z) : Prop :=
  mrun_fin M' fb s' st' str sm' e' /\ PMSP.src_step (PQMA.p_src s) (PQMA.p_src s') sm sm' /\ (e = true -> e' = true)
  /\ L5.defined M' (o_ec fb) 16.
Definition parse_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb cat n : Z) (s : PQMA.mpst) (st : PQMA.ast) (str : PM.vstr) (sm : PM.strm) (e : bool),
    ri_inv HI (mown s st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r 8 -> ffroomM 8 FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    margs3 R fb s st sm n ->
    mrun_pre M fb s st str sm e n -> incl (PM.vs_own str) LBX -> minv s -> bb_room s sm -> PMSPA.ec_at segs M (o_ec fb) 0 cat ->
    PMSP.credit_le (PMSPA.scA L (PM.credit_add (PQMA.pot_run HV s st) PQMA.TSRES)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : PQMA.ast)
            (sm' : PM.strm) (e' : bool) (cr' : credit),
        regs_preserved R R' ->
        parse_post M' fb s s' st' str sm sm' e e' n ->
        L5CA.ahpres L ar LBX FF sp (pm_scr 8) (W_mrun fb) M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_run HV s st)) (PMSPA.scA L PMSP.cr0) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (qa_parse AQ) M model) K.

(* [comment removed for export] *)
Definition src_layer_ok : Prop :=
  PGSA.src_read_specG segs A L ar HI FCM /\ PGSA.fill_buffer_specG segs A L ar HI FCM
  /\ PGV8A.read_span_v_specG segs A L ar HI FCM (qa_read_span_v AQ) /\ PGV8A.srd_read_v_specG segs A L ar HI FCM (qa_srd_read_v AQ)
  /\ PGV8A.vu8_resize_spec segs A L ar HI FCM (qa_vu8_resize AQ) /\ PGV8A.vu8_append_spec segs A L ar HI FCM (qa_vu8_append AQ).

End Specs.

