Definition reader_read_specF (pc h : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb cat n : Z) (s : PQMA.mpst) (st : PQMA.ast)
         (str : PM.vstr) (sm : PM.strm) (e : bool) (D : list (list Z)),
    ri_inv (HIk D) (mown s st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r h -> PGSA.ffroomB FCM h FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    getr R 10%bv = Z_to_bv 64 (o_p A fb) -> getr R 11%bv = Z_to_bv 64 (o_ec A fb) ->
    mrun_pre segs A AQ AA M fb s st str sm e n -> mpst_reset s = s ->
    incl (PM.vs_own str) LBX -> minv s -> bb_room s sm -> PMSPA.ec_at segs M (o_ec A fb) 0 cat ->
    PMSP.credit_le (PM.credit_add (PMSPA.scA L (PM.credit_add (PQMA.pot_run HV s st) PQMA.TSRES)) TSRESA) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
            (s' : PQMA.mpst) (st' : PQMA.ast) (sm' : PM.strm) (e' : bool) (cr' : credit) (D' : list (list Z)),
        regs_preserved R R' ->
        parse_post segs A AQ AA M' fb s s' st' str sm sm' e e' n ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr h) (W_mrun A AQ fb) M M' ->
        PMSP.credit_keep cr cr' (PM.credit_add (PMSPA.scA L (PQMA.pot_run HV s st)) TSRESA) PMSP.cr0 ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> incl D D' ->
        ri_inv (HIk D') (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
Definition opnew_n_specA (HI : asan_iface) (NMAX : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (n sp r : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    getr R 10%bv = Z_to_bv 64 n -> 0 < n <= NMAX -> acredit_ok L cr n ->
    getr R 1%bv = Z_to_bv 64 r -> L5.ra_ok r ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 4%bv = Z_to_bv 64 (hl_tp L) -> L5CA.astk ar M sp PMSPA.OPNEW_SCR ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (Aw' : list (Z * Z)) (q : Z),
        getr R' 10%bv = Z_to_bv 64 q -> regs_preserved R R' ->
        L5CA.afresh L ar LB (FF ++ LK) M' q n ->
        L5CA.ahpres L ar LB FF sp PMSPA.OPNEW_SCR [] M M' ->
        model_rt model model' -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI ((q, n) :: LB) FF LK (adebit L cr n) Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (pa_opnew A) M model) K.
