Lemma bparser_keepS op ois s :
  0 <= op -> op + PNM.PSIZE <= 2 ^ 64 ->
  PMFA.agA M M' op PNM.PSIZE ->
  (forall B m, In (B, m) (PNM.bparser_own s) -> 0 <= B /\ B + m <= 2 ^ 64 /\ PMFA.agA M M' B m) ->
