(* [comment removed for export] *)
Section Obj.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable vp : Z.
Variable vpa : Z.
Abbreviation mparser_at := (PQMA.mparser_at segs A accA annA vp).
Abbreviation adaptor_at := (PQMA.adaptor_at segs A accA annA vpa).
Variables M M' : mem.
Variables NT Y NS : Z -> Prop.
Hypothesis AGX : forall a n, 0 <= a -> a + n <= 2 ^ 64 -> (forall i, a <= i < a + n -> NT i) -> L5C.agree_on M M' a n.
Hypothesis DKY : forall i, Y i -> M (Z_to_bv 64 i) <> None -> M' (Z_to_bv 64 i) <> None.
Hypothesis SHX : forall a n, (forall i, a <= i < a + n -> NS i) -> PMFA.agsh M M' a n.
Let agx := (PNBOA.agx M M' NT AGX).
Let dkx := (PNBOA.dkx M M' Y DKY).
Let accx := (PNBOA.accx M M' NS SHX).
Let annx := (PNBOA.annx M M' NS SHX).
Local Ltac u64x AG H := apply (L5C.u64_at_agree segs M M'); [eapply (L5C.agree_on_sub M M'); [exact AG|lia|lia]|lia|lia|exact H].
Local Ltac u32x AG H := apply (PMF.u32_at_agree segs M M'); [eapply (L5C.agree_on_sub M M'); [exact AG|lia|lia]|lia|lia|exact H].
Local Ltac u8x AG H := apply (L5C.u8_at_agree segs M M'); [eapply (L5C.agree_on_sub M M'); [exact AG|lia|lia]|lia|lia|exact H].

