Lemma kstr_keep_x o x : 0 <= o -> o + 24 <= 2 ^ 64 -> (forall i, o <= i < o + 24 -> NT i) -> (forall i, o <= i < o + 24 -> Y i) -> (forall i, o <= i < o + 24 -> NS i) ->
  (forall B m, In (B, m) (PM.vs_own x) -> forall i, B <= i < B + m -> Y i) ->
  (forall B m, In (B, m) (PM.vs_own x) -> forall i, B <= i < B + m -> NS i) ->
