(* [comment removed for export] *)
Lemma mparser_at_xfer op ois s s' :
  0 <= op -> op + PQMA.PSIZE <= 2 ^ 64 ->
  mparser_at M op ois s -> (forall i, op <= i < op + PQMA.PSIZE -> Y i) -> (forall i, op <= i < op + PQMA.PSIZE -> NS i) ->
  (forall i, op <= i < op + 8 -> NT i) -> (forall i, op + 16 <= i < op + 24 -> NT i) ->
  (forall i, op + 32 <= i < op + 264 -> NT i) -> (forall i, op + 320 <= i < op + 328 -> NT i) ->
  L5.u8_at segs M' (op + 8) (PQMA.p_more s') -> L5.u8_at segs M' (op + 9) (PQMA.p_done s') -> L5.u32_at segs M' (op + 12) (PQMA.p_depth s') ->
  (PQMA.p_more s' = 0 \/ PQMA.p_more s' = 1) -> (PQMA.p_done s' = 0 \/ PQMA.p_done s' = 1) -> 0 <= PQMA.p_depth s' <= PQMA.MAX_DEPTH + 1 ->
  PM.src_fields_at segs accA M' (op + PQMA.OFF_SRC) ois (ois + 16) (PQMA.p_src s') ->
  PM.vstr_at segs accA M' (op + PQMA.OFF_TB) (PQMA.p_tb s') ->
  PGV8.v8_at segs accA annA M' (op + PQMA.OFF_BB) (PQMA.p_bb s') ->
  PQMA.mvec_at segs accA annA M' (op + PQMA.OFF_STK) (PQMA.p_sb s') (PQMA.p_sk s') (PQMA.p_stk s') ->
  mparser_at M' op ois s'.
Proof.
