Lemma mparser_keepS op ois s :
  0 <= op -> op + PQMA.PSIZE <= 2 ^ 64 ->
  PMFA.agA M M' op PQMA.PSIZE ->
  (forall B m, In (B, m) (PQMA.mparser_own s) -> 0 <= B /\ B + m <= 2 ^ 64 /\ PMFA.agA M M' B m) ->
  PQMA.mparser_at segs A accA annA vp M op ois s -> PQMA.mparser_at segs A accA annA vp M' op ois s.
