(* [comment removed for export] *)
Lemma mparser_set_moreS op ois s v :
  0 <= op -> op + PQMA.PSIZE <= 2 ^ 64 ->
  mem_grows M M' -> PMFA.agA M M' op 8 -> PMFA.agA M M' (op + 9) 391 -> PMFA.agsh M M' op PQMA.PSIZE -> L5.u8_at segs M' (op + 8) v -> (v = 0 \/ v = 1) ->
