Variable segs : list Segment.
Variable A : pm_addrs.
Variable vp : Z.
Abbreviation mparser_at := (PQMA.mparser_at segs A accA annA vp).
Variables (L : asan_layout) (ar : asan_run).
Variables (LBX : list (Z * Z)) (FF : list fframe) (sp scr : Z) (Wx : list L5.range) (M M' : word -> option byte).
Variables (op ois lo hi : Z) (s : PQMA.mpst) (src src' : PM.srcst).
Let X : list (Z * Z) := PM.src_own src ++ PQMA.mrest_own s.
Let LB : list (Z * Z) := X ++ LBX.
Let W : list L5.range := PGS.W_srcG (op + PQMA.OFF_SRC) ois src ++ Wx.

Hypothesis Hlay : lo <= op /\ op + PQMA.PSIZE <= hi /\ lo <= ois /\ ois + 272 <= hi /\ hi <= 2 ^ 47 /\ 0 <= lo.
Hypothesis Hdis : op + PQMA.PSIZE <= ois \/ ois + 272 <= op.
Hypothesis HFA : app_mem lo (hi - lo).
Hypothesis HFR : forall a, lo <= a < hi -> aclient L ar LB FF sp scr a /\ aclient L ar LB FF sp scr (S a).
Hypothesis HBA : forall b, In b LB -> 0 < snd b /\ fst b mod 16 = 0 /\ app_mem (fst b) (snd b).
Hypothesis HA : forall b, In b X -> apart (fst b) (snd b) lo (hi - lo).
Hypothesis HN : List.NoDup (map fst X).
Hypothesis HE : forall b1 b2, In b1 X -> In b2 X -> fst b1 <> fst b2 -> apart (fst b1) (snd b1) (fst b2) (snd b2).
Hypothesis HC : Forall (fun r => apart (fst r) (snd r) lo (hi - lo) /\ (forall b, In b (PQMA.mrest_own s) -> apart (fst r) (snd r) (fst b) (snd b)) /\ app_mem (fst r) (snd r)) Wx.
Hypothesis HP : L5CA.ahpres L ar LB FF sp scr W M M'.
Hypothesis HOW : mparser_at M op ois (PQMA.with_src s src).
Hypothesis HSRC : PM.src_fields_at segs accA M' (op + PQMA.OFF_SRC) ois (ois + 16) src'.

