Module PQRHA.

(* [comment removed for export] *)
Definition mparser_init (qc b : Z) : PQMA.mpst :=
  PQMA.MPST 1 0 0 (PM.SRC qc qc 0) (PM.VShort 0) 0 PGV8.V8Null 0 b 0 [PQMA.ms_root].
Definition ast_init (b' : Z) : PQMA.ast := PQMA.AST [PQMA.lv_root] b' 0 (PM.VShort 0) 0 (PM.VShort 0) 0.

(* [comment removed for export] *)
Definition rdr_cost (L : heap_layout) : credit :=
  PM.credit_add (PM.cost1 L PM.CHUNK) (PM.credit_add (PM.cost1 L PQMA.PSZ) (PM.cost1 L PQMA.LSZ)).

Definition RDRC_H : Z := 7.
Definition PCTOR_H : Z := 6.
Definition ACTOR_H : Z := 2.
Definition RDRD_H : Z := 3.
(* [comment removed for export] *)
Definition RSIZE : Z := 504.

Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable AQ : pq_addrs.
Variable AA : pm_asan_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.

Abbreviation accA := PMSPA.accA.
Abbreviation annA := PQRA.annA.
Abbreviation iss_at := (PM.iss_at segs A accA).
Abbreviation mparser_at := (PQMA.mparser_at segs A accA annA (pa_vp_parser A)).
Abbreviation adaptor_at := (PQMA.adaptor_at segs A accA annA (qa_vp_adaptor AQ)).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation ffroomM := (PGSA.ffroomB PQRA.FCM).
Abbreviation frame_okM := PQRA.frame_okM.
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSP.cfg segs).
Abbreviation HV := (PMSPA.HV L ar).
Abbreviation o_p := (PQRA.o_p A).
Abbreviation o_a := (PQRA.o_a A AQ).
Abbreviation o_v := (PQRA.o_v A).
Abbreviation o_is := (PQRA.o_is A).

(* [comment removed for export] *)
Definition opts_at (M : word -> option byte) (oo : Z) : Prop :=
  L5.u64_at segs M oo (pa_vp_opts A) /\ L5.u32_at segs M (oo + 16) PQMA.MAX_DEPTH /\ L5.defined M oo 24.
(* [comment removed for export] *)
Definition iss_cells (M : word -> option byte) (ois : Z) : Prop :=
  L5.u64_at segs M ois (pa_vp_iss A) /\ L5.u64_at segs M (ois + 160) (ois + 16).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition reader_ctor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb oo : Z) (str : PM.vstr) (sm : PM.strm),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r RDRC_H -> ffroomM RDRC_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    getr R 10%bv = Z_to_bv 64 (o_p fb) -> getr R 11%bv = Z_to_bv 64 (o_is fb) -> getr R 12%bv = Z_to_bv 64 (o_v fb) ->
    getr R 13%bv = Z_to_bv 64 oo ->
    aobjA FF oo 24 -> (oo + 24 <= o_p fb \/ o_p fb + RSIZE <= oo) -> oo mod 8 = 0 -> opts_at M oo -> accA M oo 24 ->
    L5.defined M (o_p fb) RSIZE -> accA M (o_p fb) RSIZE -> iss_at M (o_is fb) str sm -> PMSTA.base_okA segs A M -> PMST.loc_ok segs A M true ->
    PMSP.credit_le (PMSPA.scA L (rdr_cost HV)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (qc b b' : Z) (cr' : credit),
        regs_preserved R R' ->
        mparser_at M' (o_p fb) (o_is fb) (mparser_init qc b) -> adaptor_at M' (o_a fb) (o_v fb) (ast_init b') ->
        L5.u64_at segs M' (o_p fb + qa_off_vref AQ) (o_a fb) ->
        L5CA.ahpres L ar LB FF sp (pm_scr RDRC_H) [(o_p fb, RSIZE)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (rdr_cost HV)) (PMSPA.scA L PMSP.cr0) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PQRA.mown (mparser_init qc b) (ast_init b') ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (pa_reader_ctor A) M model) K.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition parser_ctor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb oo : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r PCTOR_H -> ffroomM PCTOR_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    getr R 10%bv = Z_to_bv 64 (o_p fb) -> getr R 11%bv = Z_to_bv 64 (o_is fb) -> getr R 12%bv = Z_to_bv 64 oo ->
    aobjA FF oo 24 -> (oo + 24 <= o_p fb \/ o_p fb + RSIZE <= oo) -> oo mod 8 = 0 -> opts_at M oo -> accA M oo 24 ->
    L5.defined M (o_p fb) PQMA.PSIZE -> accA M (o_p fb) PQMA.PSIZE -> iss_cells M (o_is fb) -> accA M (o_is fb) 272 -> PMSTA.base_okA segs A M -> PMST.loc_ok segs A M true ->
    PMSP.credit_le (PMSPA.scA L (PM.credit_add (PM.cost1 HV PM.CHUNK) (PM.cost1 HV PQMA.PSZ))) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (qc b : Z) (cr' : credit),
        regs_preserved R R' ->
        mparser_at M' (o_p fb) (o_is fb) (mparser_init qc b) ->
        L5CA.ahpres L ar LB FF sp (pm_scr PCTOR_H) [(o_p fb, PQMA.PSIZE)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PM.credit_add (PM.cost1 HV PM.CHUNK) (PM.cost1 HV PQMA.PSZ))) (PMSPA.scA L PMSP.cr0) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PQMA.mparser_own (mparser_init qc b) ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (qa_parser_ctor AQ) M model) K.

(* [comment removed for export] *)
Definition adaptor_ctor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb : Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r ACTOR_H -> ffroomM ACTOR_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    getr R 10%bv = Z_to_bv 64 (o_a fb) -> getr R 11%bv = Z_to_bv 64 (o_v fb) ->
    L5.defined M (o_a fb) PQMA.ASIZE -> accA M (o_a fb) PQMA.ASIZE -> PMSTA.base_okA segs A M ->
    PMSP.credit_le (PMSPA.scA L (PM.cost1 HV PQMA.LSZ)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (b' : Z) (cr' : credit),
        regs_preserved R R' ->
        adaptor_at M' (o_a fb) (o_v fb) (ast_init b') ->
        L5CA.ahpres L ar LB FF sp (pm_scr ACTOR_H) [(o_a fb, PQMA.ASIZE)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PM.cost1 HV PQMA.LSZ)) (PMSPA.scA L PMSP.cr0) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PQMA.aown (ast_init b') ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (qa_adaptor_ctor AQ) M model) K.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition reader_dtor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb : Z) (s : PQMA.mpst) (st : PQMA.ast),
    ri_inv HI (PQRA.mown s st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r RDRD_H -> ffroomM RDRD_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    frame_okM FF fb -> getr R 10%bv = Z_to_bv 64 (o_p fb) ->
    mparser_at M (o_p fb) (o_is fb) s -> adaptor_at M (o_a fb) (o_v fb) st -> accA M (o_p fb) RSIZE -> PQMA.mgrow_ok s -> PQMA.adaptor_ok st ->
    PMSTA.base_okA segs A M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)),
        regs_preserved R R' ->
        L5CA.ahpres L ar LBX FF sp (pm_scr RDRD_H) [(o_p fb, RSIZE)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI LBX FF LK' cr Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R (qa_reader_dtor AQ) M model) K.

End Specs.
End PQRHA.

End PnRunHA.
