Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQVA.

(* [comment removed for export] *)
Fixpoint ndig_f (f : nat) (v : Z) : Z := match f with Datatypes.O => 1 | Datatypes.S f' => if Z.ltb v 10 then 1 else 1 + ndig_f f' (v / 10) end.
Definition ndig (v : Z) : Z := ndig_f 20 v.
(* [comment removed for export] *)
Definition b64len (n : Z) : Z := (4 * n + 2) / 3.
(* [comment removed for export] *)
Definition sval (v : Z) : Z := if Z.ltb v (2 ^ 63) then v else v - 2 ^ 64.
Definition VIS_H : Z := 3.

Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable AQ : pq_addrs.
Variable AA : pm_asan_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.

Abbreviation accA := PMSPA.accA.
Abbreviation annA := PQRA.annA.
Abbreviation adaptor_at := (PQMA.adaptor_at segs A accA annA (qa_vp_adaptor AQ)).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation ffroomM := (PGSA.ffroomB PQRA.FCM).
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSP.cfg segs).
Abbreviation HV := (PMSPA.HV L ar).

(* [comment removed for export] *)
Definition view_ok (M : word -> option byte) (FF : list fframe) (LBX : list (Z * Z)) (oa p d n : Z) : Prop :=
  L5.u64_at segs M p d /\ L5.u64_at segs M (p + 8) n /\ 0 <= n < 2 ^ 26 /\ L5.defined M d n
  /\ accA M p 16 /\ accA M d n /\ (n = 0 \/ PGS.in_blk LBX d n \/ aobjA FF d n)
  /\ (p + 16 <= oa \/ oa + PQMA.ASIZE <= p) /\ (d + n <= oa \/ oa + PQMA.ASIZE <= d) /\ 0 <= d /\ d + n <= 2 ^ 47.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition vis_spec (pc : Z)
           (args : bvmap 5 word -> (word -> option byte) -> list fframe -> list (Z * Z) -> Z -> Prop)
           (pre : bvmap 5 word -> (word -> option byte) -> PQMA.ast -> Prop)
           (step : bvmap 5 word -> (word -> option byte) -> PQMA.ast -> PQMA.ast -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r oa ov : Z) (st : PQMA.ast),
    ri_inv HI (PQMA.aown st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r VIS_H -> ffroomM VIS_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 oa -> args R M FF LBX oa ->
    aobjA FF oa PQMA.ASIZE -> oa mod 8 = 0 -> aobjA FF ov 8 -> ov mod 8 = 0 -> (oa + PQMA.ASIZE <= ov \/ ov + 8 <= oa) ->
    adaptor_at M oa ov st -> accA M oa PQMA.ASIZE -> PQMA.adaptor_ok st -> PMSPA.visitor_at segs A M ov -> pre R M st ->
    PMSTA.base_okA segs A M -> PMSP.credit_le (PMSPA.scA L (PQMA.pot_adaptor HV st)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (st' : PQMA.ast) (cr' : credit),
        regs_preserved R R' ->
        adaptor_at M' oa ov st' -> PQMA.adaptor_ok st' -> step R M st st' ->
        L5CA.ahpres L ar LBX FF sp (pm_scr VIS_H) (PQMA.adaptor_W A oa) M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_adaptor HV st)) (PMSPA.scA L (PQMA.pot_adaptor HV st')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (PQMA.aown st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
Definition step_push (st st' : PQMA.ast) : Prop := PQMA.nlv st' = PQMA.nlv st + 1 /\ PQMA.kbsize st' <= PQMA.kbsize st + 2.
Definition step_pop (st st' : PQMA.ast) : Prop := PQMA.nlv st' = PQMA.nlv st - 1 /\ PQMA.kbsize st' <= PQMA.kbsize st + 2.
Definition step_val (d : Z) (st st' : PQMA.ast) : Prop := PQMA.nlv st' = PQMA.nlv st /\ PQMA.kbsize st' <= PQMA.kbsize st + d.

(* [comment removed for export] *)
Definition no_args (R : bvmap 5 word) (M : word -> option byte) (FF : list fframe) (LBX : list (Z * Z)) (oa : Z) : Prop := True.
(* [comment removed for export] *)
Definition pre_push (R : bvmap 5 word) (M : word -> option byte) (st : PQMA.ast) : Prop :=
  PQMA.nlv st <= PQMA.MAX_DEPTH /\ PQMA.kbsize st + 2 <= PQMA.SMB.
(* [comment removed for export] *)
Definition pre_pop (R : bvmap 5 word) (M : word -> option byte) (st : PQMA.ast) : Prop :=
  2 <= PQMA.nlv st /\ PQMA.kbsize st + 2 <= PQMA.SMB.
(* [comment removed for export] *)
Definition pre_val (d : Z) (R : bvmap 5 word) (M : word -> option byte) (st : PQMA.ast) : Prop := PQMA.kbsize st + d <= PQMA.SMB.
Definition d_u64 (R : bvmap 5 word) : Z := ndig (bv_unsigned (getr R 11%bv)) + 2.
Definition d_i64 (R : bvmap 5 word) : Z := ndig (Z.abs (sval (bv_unsigned (getr R 11%bv)))) + 3.
Definition d_double : Z := WD.WD_MAX + 2.
Definition d_null : Z := 6.
Definition d_bool : Z := 7.
(* [comment removed for export] *)
Definition view_len (R : bvmap 5 word) (M : word -> option byte) (n : Z) : Prop :=
  exists p, getr R 11%bv = Z_to_bv 64 p /\ L5.u64_at segs M (p + 8) n /\ 0 <= n < 2 ^ 26.   (* [comment removed for export] *)
Definition args_view (R : bvmap 5 word) (M : word -> option byte) (FF : list fframe) (LBX : list (Z * Z)) (oa : Z) : Prop :=
  exists p d n, getr R 11%bv = Z_to_bv 64 p /\ aobjA FF p 16 /\ view_ok M FF LBX oa p d n.
Definition args_bstr_tag (R : bvmap 5 word) (M : word -> option byte) (FF : list fframe) (LBX : list (Z * Z)) (oa : Z) : Prop :=
  args_view R M FF LBX oa /\ getr R 12%bv = Z_to_bv 64 0.
Definition args_bool (R : bvmap 5 word) (M : word -> option byte) (FF : list fframe) (LBX : list (Z * Z)) (oa : Z) : Prop :=
  getr R 11%bv = Z_to_bv 64 0 \/ getr R 11%bv = Z_to_bv 64 1.
Definition pre_str (R : bvmap 5 word) (M : word -> option byte) (st : PQMA.ast) : Prop :=
  exists n, view_len R M n /\ PQMA.kbsize st + n + 4 <= PQMA.SMB.
Definition step_str (R : bvmap 5 word) (M : word -> option byte) (st st' : PQMA.ast) : Prop :=
  exists n, view_len R M n /\ step_val (n + 4) st st'.
Definition pre_bstr (R : bvmap 5 word) (M : word -> option byte) (st : PQMA.ast) : Prop :=
  exists n, view_len R M n /\ PQMA.kbsize st + b64len n + 4 <= PQMA.SMB /\ b64len n + 4 <= PQMA.SMK.
Definition step_bstr (R : bvmap 5 word) (M : word -> option byte) (st st' : PQMA.ast) : Prop :=
  exists n, view_len R M n /\ step_val (b64len n + 4) st st'.

(* [comment removed for export] *)
Definition v_begin_array_spec : Prop :=
  vis_spec (qa_v_begin_array AQ) no_args pre_push (fun _ _ => step_push).
Definition v_begin_object_spec : Prop :=
  vis_spec (qa_v_begin_object AQ) no_args pre_push (fun _ _ => step_push).
Definition v_end_array_spec : Prop :=
  vis_spec (qa_v_end_array AQ) no_args pre_pop (fun _ _ => step_pop).
Definition v_end_object_spec : Prop :=
  vis_spec (qa_v_end_object AQ) no_args pre_pop (fun _ _ => step_pop).
Definition v_uint64_spec : Prop :=
  vis_spec (qa_v_uint64 AQ) no_args (fun R M => pre_val (d_u64 R) R M) (fun R _ => step_val (d_u64 R)).
Definition v_int64_spec : Prop :=
  vis_spec (qa_v_int64 AQ) no_args (fun R M => pre_val (d_i64 R) R M) (fun R _ => step_val (d_i64 R)).
Definition v_double_spec : Prop :=
  vis_spec (qa_v_double AQ) no_args (pre_val d_double) (fun _ _ => step_val d_double).
Definition v_null_spec : Prop :=
  vis_spec (qa_v_null AQ) no_args (pre_val d_null) (fun _ _ => step_val d_null).
Definition v_bool_spec : Prop :=
  vis_spec (qa_v_bool AQ) args_bool (pre_val d_bool) (fun _ _ => step_val d_bool).
Definition v_string_spec : Prop :=
  vis_spec (qa_v_string AQ) args_view pre_str step_str.
Definition v_bstr_tag_spec : Prop :=
  vis_spec (qa_v_bstr_tag AQ) args_bstr_tag pre_bstr step_bstr.
Definition v_bstr_raw_spec : Prop :=
  vis_spec (qa_v_bstr_raw AQ) args_view pre_bstr step_bstr.
Definition v_flush_spec : Prop :=
  vis_spec (qa_v_flush AQ) no_args (fun _ _ _ => True) (fun _ _ => step_val 0).

(* [comment removed for export] *)
Record vis_ok : Prop := VISOK {
  vo_begin_array : v_begin_array_spec; vo_begin_object : v_begin_object_spec;
  vo_end_array : v_end_array_spec; vo_end_object : v_end_object_spec;
  vo_uint64 : v_uint64_spec; vo_int64 : v_int64_spec; vo_double : v_double_spec;
  vo_null : v_null_spec; vo_bool : v_bool_spec; vo_string : v_string_spec;
  vo_bstr_tag : v_bstr_tag_spec; vo_bstr_raw : v_bstr_raw_spec; vo_flush : v_flush_spec }.

End Specs.
End PQVA.

End PnVisA.
Module PnRunAa.
From OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib Require BvWfKernel.
