Section Sem.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable vp : Z.
Variables M M' : mem.
Let snt := (PNBOA.snt M M').
Let sns := (PNBOA.sns M M').
Let sAGX := (PNBOA.sAGX M M').
Let sSHX := (PNBOA.sSHX M M').

(* [comment removed for export] *)
Lemma mparser_set_fldS op ois s mo dp :
  0 <= op -> op + PQMA.PSIZE <= 2 ^ 64 ->
  mem_grows M M' -> PMFA.agA M M' op 8 -> PMFA.agA M M' (op + 16) 384 -> PMFA.agsh M M' op PQMA.PSIZE ->
  L5.u8_at segs M' (op + 8) mo -> L5.u8_at segs M' (op + 9) (PQMA.p_done s) -> L5.u32_at segs M' (op + 12) dp ->
  (mo = 0 \/ mo = 1) -> 0 <= dp <= PQMA.MAX_DEPTH + 1 ->
  (forall B m, In (B, m) (PQMA.mparser_own s) -> 0 <= B /\ B + m <= 2 ^ 64 /\ PMFA.agA M M' B m) ->
  PQMA.mparser_at segs A accA annA vp M op ois s -> PQMA.mparser_at segs A accA annA vp M' op ois (set_fld s mo dp).
Proof.
