(* [comment removed for export] *)
Lemma mparser_revecS op ois s b' k' stk' :
  0 <= op -> op + PQMA.PSIZE <= 2 ^ 64 ->
  (forall i, op <= i < op + 376 -> snt i) ->
  (forall i, op <= i < op + PQMA.PSIZE -> sns i) ->
  (forall i, op <= i < op + PQMA.PSIZE -> M (Z_to_bv 64 i) <> None -> M' (Z_to_bv 64 i) <> None) ->
  (forall B m, In (B, m) (rest_own s) -> 0 <= B /\ B + m <= 2 ^ 64 /\ PMFA.agA M M' B m) ->
  PQMA.mvec_at segs accA annA M' (op + 376) b' k' stk' ->
  PQMA.mparser_at segs A accA annA vp M op ois s -> PQMA.mparser_at segs A accA annA vp M' op ois (set_vec s b' k' stk').
Proof.
