(* [comment removed for export] *)
Lemma pot_rest_nonneg (L : heap_layout) (M : mem) vp op ois s : PQMA.mparser_at segs A accA annA vp M op ois s -> PQMA.mgrow_ok s ->
  0 <= HeapIface.hl_k_per_malloc L -> 0 <= HeapIface.hl_b_overhead L ->
  0 <= fst (PQMA.pot_textM L (PQMA.p_tb s)) + fst (PGV8.pot_v8 L (PQMA.p_bb s) (PQMA.p_bg s))
  /\ 0 <= snd (PQMA.pot_textM L (PQMA.p_tb s)) + snd (PGV8.pot_v8 L (PQMA.p_bb s) (PQMA.p_bg s))
  /\ 0 <= PQMA.p_sk s <= 11.
Proof.
