Lemma pot_adaptor_nonneg (L : heap_layout) (M : mem) oa ov st vpa : PQMA.adaptor_at segs A accA annA vpa M oa ov st -> PQMA.adaptor_ok st ->
  0 <= HeapIface.hl_k_per_malloc L -> 0 <= HeapIface.hl_b_overhead L ->
  0 <= fst (PQMA.pot_adaptor L st) /\ 0 <= snd (PQMA.pot_adaptor L st).
