.fuzz_msgpack_encoder.lib.Mh_0092.L5LazyA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0179.L5DefsA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.asan.Mh_0210.L5CoreA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0018.PmLayout OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0024.PmLayoutA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmModel OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PmStatics OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0092.PmStaticsA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PmSpecsA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0090.PgSrc OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.PgV8 OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PgSrcA OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0213.PgV8A OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0092.PnModelA.
Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQSAXQ.
Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.

Local Abbreviation mvec_at := (PQMA.mvec_at segs PMSPA.accA PMSPA.annA).
Local Abbreviation PSZ := PQMA.PSZ.

(* [comment removed for export] *)
Definition vec_pre (M : word -> option byte) (v b k : Z) (stk : list PQMA.mstate) (own : list (Z * Z)) : Prop :=
  (L5.u64_at segs M v 0 /\ L5.u64_at segs M (v + 8) 0 /\ L5.u64_at segs M (v + 16) 0 /\ b = 0 /\ k = 0 /\ stk = [] /\ own = [])
  \/ (mvec_at M v b k stk /\ own = PQMA.mvec_own b k).

(* [comment removed for export] *)
Definition full_or_empty (k : Z) (stk : list PQMA.mstate) (own : list (Z * Z)) : Prop := own = [] \/ Z.of_nat (length stk) = 2 ^ k.
Definition k_next (b k : Z) : Z := if Z.eqb b 0 then 0 else k + 1.
Definition push_out (b k : Z) (stk : list PQMA.mstate) (own : list (Z * Z)) (b' k' : Z) (cr cr' : credit) : Prop :=
  (own <> [] /\ Z.of_nat (length stk) < 2 ^ k /\ b' = b /\ k' = k /\ cr' = cr)
  \/ (full_or_empty k stk own /\ k' = k_next b k /\ cr' = adebit L cr (PSZ * 2 ^ k')).

(* [comment removed for export] *)
Definition arg_ok (FF : list fframe) (sp v p n : Z) : Prop :=
  (PMSPA.aobjA FF p n \/ (sp <= p /\ p + n <= ar_sptop ar)) /\ (p + n <= v \/ v + 24 <= p).
(* [comment removed for export] *)
Definition arg_cell (M : word -> option byte) (FF : list fframe) (sp v p n : Z) : Prop :=
  p mod n = 0 /\ PMSPA.accA M p n /\ arg_ok FF sp v p n /\ byte_at M (HeapIfaceA.S p) 0.

(* [comment removed for export] *)
Definition push_spec_at (pc : Z) (cells : list fframe -> Z -> Z -> (word -> option byte) -> bvmap 5 word -> PQMA.mstate -> Prop)
           (dom : Z -> list PQMA.mstate -> list (Z * Z) -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (v b k : Z) (stk : list PQMA.mstate) (own : list (Z * Z))
         (c : PQMA.mstate) (sp r : Z),
    ri_inv HI (own ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r 0 -> PMSPA.ffrsA FF sp ->
    getr R 10%bv = Z_to_bv 64 v -> PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> PMSPA.accA M v 24 ->
    vec_pre M v b k stk own -> dom k stk own -> (full_or_empty k stk own -> k <= 10) ->
    PMSTA.base_okA segs A M ->           (* [comment removed for export] *)
    cells FF sp v M R c ->
    (full_or_empty k stk own -> acredit_ok L cr (PSZ * 2 ^ (k_next b k))) ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
            (b' k' : Z) (cr' : credit),
        regs_preserved R R' ->
        mvec_at M' v b' k' (stk ++ [c]) -> PMSPA.accA M' v 24 -> PMSTA.base_okA segs A M' ->
        push_out b k stk own b' k' cr cr' ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [(v, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PQMA.mvec_own b' k' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@PMSPA.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSPA.cfg segs fx R pc M model) K.

(* [comment removed for export] *)
Definition cells_cont (FF : list fframe) (sp v : Z) (M : word -> option byte) (R : bvmap 5 word) (c : PQMA.mstate) : Prop :=
  exists p1 p2, getr R 11%bv = Z_to_bv 64 p1 /\ getr R 12%bv = Z_to_bv 64 p2
    /\ arg_cell M FF sp v p1 4 /\ arg_cell M FF sp v p2 8
    /\ L5.u32_at segs M p1 (PQMA.ms_mode c) /\ L5.u64_at segs M p2 (PQMA.ms_len c) /\ PQMA.ms_idx c = 0
    /\ 0 <= PQMA.ms_mode c < 2 ^ 31 /\ 0 <= PQMA.ms_len c < 2 ^ 64.
(* [comment removed for export] *)
Definition cells_root (FF : list fframe) (sp v : Z) (M : word -> option byte) (R : bvmap 5 word) (c : PQMA.mstate) : Prop :=
  exists p1 p2, getr R 11%bv = Z_to_bv 64 p1 /\ getr R 12%bv = Z_to_bv 64 p2
    /\ arg_cell M FF sp v p1 4 /\ arg_cell M FF sp v p2 4
    /\ L5.u32_at segs M p1 (PQMA.ms_mode c) /\ L5.u32_at segs M p2 (PQMA.ms_len c) /\ PQMA.ms_idx c = 0
    /\ 0 <= PQMA.ms_mode c < 2 ^ 31 /\ 0 <= PQMA.ms_len c < 2 ^ 31.

Definition dom_cont (k : Z) (stk : list PQMA.mstate) (own : list (Z * Z)) : Prop := own <> [].
Definition dom_root (k : Z) (stk : list PQMA.mstate) (own : list (Z * Z)) : Prop := own = [] \/ Z.of_nat (length stk) < 2 ^ k.
Definition push_cont_spec (pc : Z) : Prop := push_spec_at pc cells_cont dom_cont.
Definition push_root_spec (pc : Z) : Prop := push_spec_at pc cells_root dom_root.

(* [comment removed for export] *)
Definition ann_shrink_spec (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (v b k old : Z) (stk : list PQMA.mstate) (sp r : Z),
    ri_inv HI (PQMA.mvec_own b k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r 0 -> PMSPA.ffrsA FF sp ->
    getr R 10%bv = Z_to_bv 64 v -> getr R 11%bv = Z_to_bv 64 old -> PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> PMSPA.accA M v 24 ->
    Z.of_nat (length stk) <= old <= 2 ^ k ->
    (* [comment removed for export] *)
    L5.u64_at segs M v b -> L5.u64_at segs M (v + 8) (b + PSZ * Z.of_nat (length stk)) -> L5.u64_at segs M (v + 16) (b + PSZ * 2 ^ k) ->
    0 <= k <= 11 -> b mod 16 = 0 -> L5.defined M b (PSZ * 2 ^ k) -> PMSPA.accA M b (PSZ * old) -> PMSPA.annA M b (PSZ * old) (PSZ * 2 ^ k) ->
    (forall i, (i < length stk)%nat -> PQMA.mstate_at segs M (b + PSZ * Z.of_nat i) (nth i stk PQMA.ms_root)) ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)),
        regs_preserved R R' -> mvec_at M' v b k stk -> PMSPA.accA M' v 24 ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PQMA.mvec_own b k ++ LBX) FF LK' cr Aw' M' (vml_of model') ->
        srealizes segs SCFG (@PMSPA.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSPA.cfg segs fx R pc M model) K.

(* [comment removed for export] *)
Definition ann_delete_spec (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (v b k : Z) (stk : list PQMA.mstate) (sp r : Z),
    ri_inv HI (PQMA.mvec_own b k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r 0 -> PMSPA.ffrsA FF sp ->
    getr R 10%bv = Z_to_bv 64 v -> PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> PMSPA.accA M v 24 ->
    mvec_at M v b k stk ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)),
        regs_preserved R R' ->
        L5.defined M' b (PSZ * 2 ^ k) -> PMSPA.accA M' b (PSZ * 2 ^ k) ->
        (forall i, (i < length stk)%nat -> PQMA.mstate_at segs M' (b + PSZ * Z.of_nat i) (nth i stk PQMA.ms_root)) ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PQMA.mvec_own b k ++ LBX) FF LK' cr Aw' M' (vml_of model') ->
        srealizes segs SCFG (@PMSPA.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSPA.cfg segs fx R pc M model) K.
End Specs.
End PQSAXQ.

