Module PQSAXL.
Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.

Local Abbreviation lvec_at := (PQMA.lvec_at segs PMSPA.accA PMSPA.annA).
Local Abbreviation LSZ := PQMA.LSZ.

(* [comment removed for export] *)
Definition lvec_pre (M : word -> option byte) (v b k : Z) (lv : list PQMA.alvl) (own : list (Z * Z)) : Prop :=
  (L5.u64_at segs M v 0 /\ L5.u64_at segs M (v + 8) 0 /\ L5.u64_at segs M (v + 16) 0 /\ b = 0 /\ k = 0 /\ lv = [] /\ own = [])
  \/ (lvec_at M v b k lv /\ own = PQMA.lvec_own b k).

(* [comment removed for export] *)
Definition full_or_empty (k : Z) (lv : list PQMA.alvl) (own : list (Z * Z)) : Prop := own = [] \/ Z.of_nat (length lv) = 2 ^ k.
Definition push_out (b k : Z) (lv : list PQMA.alvl) (own : list (Z * Z)) (b' k' : Z) (cr cr' : credit) : Prop :=
  (own <> [] /\ Z.of_nat (length lv) < 2 ^ k /\ b' = b /\ k' = k /\ cr' = cr)
  \/ (full_or_empty k lv own /\ k' = PQSAXQ.k_next b k /\ cr' = adebit L cr (LSZ * 2 ^ k')).

(* [comment removed for export] *)
Definition lvpush_spec_at (pc : Z) (cells : list fframe -> Z -> Z -> (word -> option byte) -> bvmap 5 word -> PQMA.alvl -> Prop)
           (dom : Z -> list PQMA.alvl -> list (Z * Z) -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (v b k : Z) (lv : list PQMA.alvl) (own : list (Z * Z))
         (c : PQMA.alvl) (sp r : Z),
    ri_inv HI (own ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r 0 -> PMSPA.ffrsA FF sp ->
    getr R 10%bv = Z_to_bv 64 v -> PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> PMSPA.accA M v 24 ->
    lvec_pre M v b k lv own -> dom k lv own -> (full_or_empty k lv own -> k <= 10) ->
    PMSTA.base_okA segs A M ->           (* [comment removed for export] *)
    cells FF sp v M R c ->
    (full_or_empty k lv own -> acredit_ok L cr (LSZ * 2 ^ (PQSAXQ.k_next b k))) ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
            (b' k' : Z) (cr' : credit),
        regs_preserved R R' ->
        lvec_at M' v b' k' (lv ++ [c]) -> PMSPA.accA M' v 24 -> PMSTA.base_okA segs A M' ->
        push_out b k lv own b' k' cr cr' ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [(v, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PQMA.lvec_own b' k' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@PMSPA.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSPA.cfg segs fx R pc M model) K.

(* [comment removed for export] *)
Definition lvl_eo (k : Z) : Z := if Z.eqb k 2 then 0 else 1.
(* [comment removed for export] *)
Definition cells_lvl (FF : list fframe) (sp v : Z) (M : word -> option byte) (R : bvmap 5 word) (c : PQMA.alvl) : Prop :=
  exists p1 p2, getr R 11%bv = Z_to_bv 64 p1 /\ getr R 12%bv = Z_to_bv 64 p2
    /\ PQSAXQ.arg_cell ar M FF sp v p1 4 /\ PQSAXQ.arg_cell ar M FF sp v p2 4
    /\ L5.u32_at segs M p1 (PQMA.lv_t c) /\ L5.u32_at segs M p2 (PQMA.lv_k c) /\ PQMA.lv_eo c = lvl_eo (PQMA.lv_k c)
    /\ 0 <= PQMA.lv_t c < 2 ^ 31 /\ 0 <= PQMA.lv_k c < 2 ^ 31.

Definition dom_live (k : Z) (lv : list PQMA.alvl) (own : list (Z * Z)) : Prop := own <> [].
Definition dom_empty (k : Z) (lv : list PQMA.alvl) (own : list (Z * Z)) : Prop := own = [].
Definition dom_any (k : Z) (lv : list PQMA.alvl) (own : list (Z * Z)) : Prop := True.
Definition lvpush_spec (pc : Z) : Prop := lvpush_spec_at pc cells_lvl dom_live.
Definition lvpush_empty_spec (pc : Z) : Prop := lvpush_spec_at pc cells_lvl dom_empty.
Definition lvpush_any_spec (pc : Z) : Prop := lvpush_spec_at pc cells_lvl dom_any.

Lemma lvpush_any_live pc : lvpush_any_spec pc -> lvpush_spec pc.
Proof. intros H fx R M model K LBX FF LK Aw cr v b k lv own c sp r. intros; eapply H; eauto. exact I. Qed.
Lemma lvpush_any_empty pc : lvpush_any_spec pc -> lvpush_empty_spec pc.
Proof. intros H fx R M model K LBX FF LK Aw cr v b k lv own c sp r. intros; eapply H; eauto. exact I. Qed.

End Specs.
End PQSAXL.

End PnSpecsAXl.
