Module PQAKG3.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Definition regl (ix : list nat) (vals : nat -> Z) (Rx : bvmap 5 word) : Prop :=
  forall j, In j ix -> getr Rx (reg j) = Z_to_bv 64 (vals j).
Definition subl (l KS : list nat) : bool := forallb (fun k => existsb (Nat.eqb k) KS) l.
Lemma subl_in (KS l : list nat) : subl l KS = true -> forall k, In k l -> In k KS.
Proof.
  unfold subl. induction l as [|a l IH]; intros H k Hk; [destruct Hk|]. cbn [forallb] in H. apply andb_prop in H as [H1 H2].
  destruct Hk as [<-|Hk]; [|apply IH; assumption].
  apply existsb_exists in H1. destruct H1 as (y & Hy & E). apply Nat.eqb_eq in E. subst y. exact Hy.
Qed.
Lemma regl_keep ix vals KS (R R' : bvmap 5 word) :
  (forall x, In x KS -> getr R' (reg x) = getr R (reg x)) -> subl ix KS = true -> regl ix vals R -> regl ix vals R'.
Proof. intros KSx SUB Q j Hj. rewrite (KSx j (subl_in KS ix SUB j Hj)). exact (Q j Hj). Qed.
Lemma regl_pres ix vals (R R' : bvmap 5 word) :
  regs_preserved R R' -> subl ix L5SAR.cs_all = true -> regl ix vals R -> regl ix vals R'.
Proof. intros RP SUB Q j Hj. rewrite (L5SAR.cs_of_preserved R R' j RP (subl_in L5SAR.cs_all ix SUB j Hj)). exact (Q j Hj). Qed.
Lemma regl_sub ix ix' vals (R : bvmap 5 word) : subl ix' ix = true -> regl ix vals R -> regl ix' vals R.
Proof. intros SUB Q j Hj. exact (Q j (subl_in ix ix' SUB j Hj)). Qed.
(* [comment removed for export] *)
Lemma regl_cons ix vals (R : bvmap 5 word) j v : getr R (reg j) = Z_to_bv 64 v -> vals j = v -> regl ix vals R -> regl (j :: ix) vals R.
Proof. intros H E Q i [<-|Hi]; [rewrite E; exact H| exact (Q i Hi)]. Qed.
Lemma bvu_rng (x : word) : 0 <= bv_unsigned x < 2 ^ 64.
Proof. pose proof (bv_unsigned_in_range 64 x) as B. change (bv_modulus 64) with (2 ^ 64) in B. exact B. Qed.
End PQAKG3.

