(* [comment removed for export] *)
Lemma ks_grow SM s g need n' p' :
  PQMA.ks_ok SM s g -> PM.vs_cap s < need -> need <= SM -> 0 <= n' <= SM -> n' <= need ->
  let c' := gcount (PM.vs_cap s) need in
  PQMA.ks_ok SM (PM.VLong c' n' p') (g + 1) /\ 2 * PQMA.ks_alloc s <= c' /\ 48 <= c' /\ c' <= 2 * SM + 8 /\ c' mod 8 = 0
  /\ n' < c' /\ 26 <= c' <= PQMA.KCAP /\ c' mod 2 = 0 /\ g < PQMA.GMAX.
Proof.
