  HeapIface.hl_k_per_malloc HV = HeapIfaceA.hl_k_per_malloc L -> HeapIface.hl_b_overhead HV = HeapIfaceA.hl_b_overhead L ->
  0 <= HeapIfaceA.hl_k_per_malloc L -> 0 <= HeapIfaceA.hl_b_overhead L -> 1 <= hl_b_lin L ->
  PQMA.ks_alloc s' = c' -> 2 * PQMA.ks_alloc s <= c' -> g < PQMA.GMAX ->
  c' <= 2 * SM + 8 -> PQMA.ks_alloc s <= SM -> 0 <= PQMA.ks_alloc s ->
  PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM s g)) cr ->
