(* [comment removed for export] *)
Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.
Abbreviation accA := PMSPA.accA.
Abbreviation kstr_at := (PQMA.kstr_at segs accA).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation ffroomM := (PGSA.ffroomB PQRA.FCM).
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSP.cfg segs).
Abbreviation HV := (PMSPA.HV L ar).

(* [comment removed for export] *)
Definition SMMAX : Z := 2 ^ 29 - 2 ^ 16.

(* [comment removed for export] *)
Definition memmove_n_spec : Prop := HAR.amemcpyN_spec_at L ar SCFG (fun _ : list (list Z) => HI) (hl_asan_memmove L).
Definition memmove_libc_n_spec (IL : icpt_layout) : Prop := HAR.amemcpyN_spec_at L ar SCFG (fun _ : list (list Z) => HI) (icl_memmove IL).

(* [comment removed for export] *)
Definition PB_H : Z := 1.
Definition pb_specA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o c sp r SM g : Z) (x : PM.vstr),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r PB_H -> ffroomM PB_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 c -> 0 <= c < 256 -> aobjA FF o 24 -> o mod 8 = 0 ->
    kstr_at M o x -> PQMA.ks_ok SM x g -> SM <= SMMAX -> PM.vs_size x < SM ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> kstr_at M' o x' -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + 1 ->
        (PM.vs_size x < PM.vs_cap x -> PM.vs_own x' = PM.vs_own x /\ g' = g) ->
        L5CA.ahpres L ar LB FF sp (pm_scr PB_H) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
Definition src_okA (M : word -> option byte) (LB : list (Z * Z)) (FF : list fframe) (q n : Z) : Prop :=
  0 <= q /\ q + n <= 2 ^ 47 /\ accA M q n
  /\ (n = 0 \/ (hl_img_lo L <= q /\ q + n <= hl_img_hi L /\ (forall i, 0 <= i < n -> ~ hl_rt_static L (q + i)) /\ (forall LB' FF' LK' cr' Aw' M' V', ri_inv HI LB' FF' LK' cr' Aw' M' V' -> accA M' q n)) \/ PGS.in_blk LB q n \/ aobjA FF q n)   (* [comment removed for export] *)
  /\ exists bs, length bs = Z.to_nat n /\ rdn segs M (Z_to_bv 64 q) (length bs) = Some bs.

(* [comment removed for export] *)
Definition INS_H : Z := 2.
Definition ins_specA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o q n sp r SM g : Z) (x : PM.vstr),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r INS_H -> ffroomM INS_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 (PM.vs_data o x + PM.vs_size x) ->
    getr R 12%bv = Z_to_bv 64 q -> getr R 13%bv = Z_to_bv 64 (q + n) -> getr R 14%bv = Z_to_bv 64 n ->
    0 <= n -> PM.vs_size x + n <= SM -> src_okA M LB FF q n -> (q + n <= o \/ o + 24 <= q) ->
    aobjA FF o 24 -> o mod 8 = 0 -> kstr_at M o x -> PQMA.ks_ok SM x g -> SM <= SMMAX ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> kstr_at M' o x' -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + n ->
        (PM.vs_size x + n <= PM.vs_cap x -> PM.vs_own x' = PM.vs_own x /\ g' = g) ->
        L5CA.ahpres L ar LB FF sp (pm_scr INS_H) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
Definition FROM_H : Z := 2.
Definition nchars (v : Z) : Z := PQVA.ndig (Z.abs (PQVA.sval v)) + (if Z.ltb v (2 ^ 63) then 0 else 1).
Definition from_specA (pc : Z) (d : Z -> Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o v sp r SM g : Z) (x : PM.vstr),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r FROM_H -> ffroomM FROM_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 v -> 0 <= v < 2 ^ 64 -> getr R 11%bv = Z_to_bv 64 o -> aobjA FF o 24 -> o mod 8 = 0 ->
    kstr_at M o x -> PQMA.ks_ok SM x g -> SM <= SMMAX -> PM.vs_size x + 20 <= SM ->
    PMSTA.base_okA segs A M ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> kstr_at M' o x' -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + d v ->
        L5CA.ahpres L ar LB FF sp (pm_scr FROM_H) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
Definition fromu_specA (pc : Z) : Prop := from_specA pc PQVA.ndig.
Definition fromi_specA (pc : Z) : Prop := from_specA pc nchars.

(* [comment removed for export] *)
Definition B64_H : Z := 2.
Definition b64_specA (pc alph : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o q n sp r SM g : Z) (x : PM.vstr),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r B64_H -> ffroomM B64_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 q -> getr R 11%bv = Z_to_bv 64 (q + n) -> getr R 12%bv = Z_to_bv 64 alph -> getr R 13%bv = Z_to_bv 64 o ->
    0 <= n < 2 ^ 26 -> src_okA M LB FF q n -> (q + n <= o \/ o + 24 <= q) ->
    aobjA FF o 24 -> o mod 8 = 0 -> kstr_at M o x -> PQMA.ks_ok SM x g -> SM <= SMMAX -> PM.vs_size x + PQVA.b64len n <= SM ->
    PMSTA.base_okA segs A M ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> kstr_at M' o x' -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + PQVA.b64len n ->
        L5CA.ahpres L ar LB FF sp (pm_scr B64_H) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

End Specs.

