Open Scope Z_scope.

Module PQSAXE.
Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.

Definition dom_any (k : Z) (stk : list PQMA.mstate) (own : list (Z * Z)) : Prop := True.
Definition epush_spec (pc : Z) : Prop := PQSAXQ.push_spec_at segs A L ar HI pc (PQSAXQ.cells_cont segs ar) dom_any.

(* [comment removed for export] *)
Lemma epush_cont pc : epush_spec pc -> PQSAXQ.push_cont_spec segs A L ar HI pc.
Proof.
  intros EP fx R M model K LBX FF LK Aw cr v b k stk own c sp r HH AM K0 ENT FRS A10 AO V8 ACC VP DOM FK BASE CELLS CR KONT.
  exact (EP fx R M model K LBX FF LK Aw cr v b k stk own c sp r HH AM K0 ENT FRS A10 AO V8 ACC VP I FK BASE CELLS CR KONT).
Qed.
End Specs.
End PQSAXE.

